  _ = `Samenwerken aan bundels`,
  v = `(Optioneel) Je kunt ervoor kiezen om andere ontwikkelaars uit te nodigen om hun spellen aan jouw bundel toe te voegen. Je bent er als eigenaar van de bundel verantwoordelijk voor met de andere ontwikkelaars te coördineren. Je bent als eigenaar ook de enige die de bundel in de Steam-winkel kan publiceren. Uitgenodigde partijen mogen kiezen welke spellen of pakketten ze toevoegen. Elke keer dat een pakket aan de bundel wordt toegevoegd of dat het kortingspercentage verandert, moeten alle samenwerkingspartners goedkeuren dat hun spel in de bundel wordt opgenomen voordat die gepubliceerd kan worden.`,
