  it = `Een uitverkoop waarvoor geen gepersonaliseerde URL is ingevoerd, zal niet zichtbaar zijn als winkel op de uitverkooppagina of aangesproken worden om uitgelicht te worden, aangezien deze functies gebruik maken van een URL.`,
