  va = `Uitgavedatum: %1$s`,
  ya = `Binnenkort verwacht: %1$s`,
  ba = `Winkeltags: %1$s`,
  xa = `Spel verwijderen`,
  Sa = `Spel opnieuw toevoegen`,
  Ca = `Spel uitnodigen`,
  wa = `Alle spellen uitnodigen`,
  Ta = `Alle spellen verwijderen`,
  Ea = `Bijwerken mislukt. Bekijk de console voor meer informatie.`,
  Da = `Alle apps die wachten op beoordeling uitnodigen`,
  Oa = `Alle apps die wachten op beoordeling verwijderen`,
  ka = `Status wijzigen van alle apps die wachten op beoordeling. Deze actie kan NIET ongedaan gemaakt worden. Klik op OK om door te gaan.`,
  Aa = `De wijzigingen voor deze bundel zijn voltooid. Je kunt dit dialoogvenster nu sluiten.`,
  ja = `Verzoek van partner:`,
  Ma = `Verzoek aangemaakt om:`,
  Na = `Verzoek accepteren`,
  Pa = `Verzoek weigeren`,
  Fa = `Weet je het zeker? Hierdoor wordt de status van '%1$s' gewijzigd en wordt de aanvrager van het verzoek via e-mail op de hoogte gebracht van onze beslissing.`,
  Ia = `De evenementpagina zal een of meer secties hebben waar enkel spellen met kortingen worden weergegeven. Er zullen ook een of meer secties op de evenementpagina zijn waar prioriteit wordt gegeven aan het uitlichten van spellen met kortingen.`,
  La = `Registratie voor %1$s`,
  Ra = `Status: komt niet in aanmerking voor deelname`,
  za = `Status: komt niet meer in aanmerking voor deelname vanwege de uitgave van het spel`,
  Ba = `Status: Komt niet in aanmerking omdat mods niet kunnen deelnemen aan het Steam Next Festival`,
  Va = `Status: niet beoordeeld voor deelname`,
  Ha = `Status: je verzoek voor deelname wacht op beoordeling`,
  Ua = `Het verzochte evenement (%1$s) bestaat niet.`,
  Wa = `Het evenement is afgelopen. Het is niet meer mogelijk om verzoeken in te dienen.`,
  Ga = `Het spel (%1$s) neemt al deel aan het evenement (%2$s).`,
  Ka = `Ga hier naar de registratiepagina.`,
  qa = `Ons beoordelingsteam heeft vastgesteld dat %1$s niet voldoet aan de selectiecriteria van dit evenement.`,
  Ja = `Spellen die voor de verschillende officiële thematische uitverkopen van Steam worden uitgenodigd, moeten duidelijk aansluiten bij het thema van het evenement en voldoen aan de selectiecriteria voor deelname. Dit wordt bepaald door te kijken naar de tags die aan de winkelpagina van het spel zijn gekoppeld en de gameplay die op de winkelpagina wordt beschreven en weergegeven.`,
  Ya = `Bij het opstellen van de lijst met spellen die we willen uitnodigen, kijken we vooral naar het volgende:`,
  Xa = `<2>Belangrijke winkeltags</2> voor het thema. Je kunt de tags die momenteel aan je spel zijn gekoppeld bekijken en wijzigen via de <1>tagwizard</1>.`,
  Za = `<1>Beschrijving op de winkelpagina</1> we bekijken de trailer, de screenshots en de beschrijving van het spel om te zien of het binnen het thema van het evenement past.`,
  Qa = `Ons beoordelingsteam had %1$s oorspronkelijk niet overwogen voor dit evenement.`,
  $a = `Deelnemingsvoorwaarden`,
  eo = `Verzoek om deel te nemen met %1$s`,
  to = `Verzoek om deel te nemen met %1$s is gesloten.`,
  no = `Beoordeling aanvragen voor %1$s`,
  ro = `Als je van mening bent dat je spel duidelijk overeenkomt met bovenstaande selectiecriteria, kun je ons hiervan op de hoogte brengen via deze verzoeksprocedure. We beoordelen je spel op basis van de winkelpagina. Het is dus belangrijk dat je winkelpagina (inclusief trailers, screenshots en tags) de kern van je spel goed weergeeft en aantoont dat het in aanmerking komt voor dit evenement.`,
  io = `Na beoordeling denken we niet dat %1$s past bij het thema van dit evenement. Houd de planning in de gaten voor toekomstige evenementen die beter aansluiten bij het thema en/of de gameplay van je titel.`,
  ao = `Verzoeksprocedure starten`,
  oo = `Je verzoek is ingediend`,
  so = `Je verzoek is ingediend. Deze aanvragen worden regelmatig beoordeeld. We sturen je een e-mail met de resultaten van het verzoek.`,
  co = `De verzoeksprocedure`,
  lo = `Deze aanvragen worden regelmatig beoordeeld in de periode voor en tijdens %1$s. We sturen je een e-mail met de resultaten van het verzoek.`,
  uo = `Resultaat verzoek: afgewezen`,
  fo = `Ons team heeft je spel opnieuw beoordeeld en vastgesteld dat het niet goed aansluit bij %1$s.`,
  po = `Er zijn het hele jaar door speciale evenementen, dus kijk gerust eens in de lijst met <1>aankomende evenementen</1> of houd de aankondigingen in de gaten voor een evenement met een thema dat beter bij je spel past.`,
  mo = `Lees voor meer informatie de %1$s`,
  ho = `documentatie over %1$s`,
  go = `Voor algemene informatie over thematische Steam-uitverkopen, waaronder de selectie- en uitnodigingsprocedure, manieren om deel te nemen, evenementzichtbaarheid en -promotie, zichtbaarheid van het spel binnen evenementen en toestemming voor opname in marketingmaterialen, ga je naar de <1>algemene documentatie voor thematische Steam-uitverkopen</1>.`,
  _o = `Hulp nodig?`,
  vo = `Als je van mening bent dat je spel helemaal voldoet aan de criteria voor deelname aan dit evenement, kun je deze verzoeksprocedure gebruiken om ons dit te laten weten.`,
  yo = `Controleer je <1>winkelpagina</1> en <2>tags</2> en houd hierbij de criteria voor dit evenement in gedachten. Aanvullende informatie als gameplay, videoclips, demo's en presentaties worden niet geaccepteerd. Alleen informatie die openbaar beschikbaar is wordt bij de beoordeling meegenomen.`,
  bo = `Vertel ons meer over je spel`,
  xo = `Gebruik het onderstaande formulier om aan te geven wat we mogelijk over het hoofd hebben gezien bij het beoordelen van de winkelpagina van je spel.`,
  So = `Verzoek indienen`,
  Co = `Er is een fout opgetreden bij het opslaan van de wijziging. Probeer het later opnieuw.`,
  wo = `Verzoek niet mogelijk`,
  To = `De uitgavedatum van je spel is ingesteld op een datum vóór de start van dit evenement. Alleen spellen die na %1$s worden uitgegeven, komen in aanmerking voor deelname.`,
  Eo = `Als je plannen zijn gewijzigd en je je spel na deze datum wilt uitgeven, wijzig dan de uitgavedatum van je spel in Steamworks.`,
  Do = `Lees voor meer informatie de <1>documentatie over uitgavedatums</1>.`,
  Oo = `Je spel is al uitgegeven. Spellen die zijn uitgegeven kunnen niet deelnemen aan dit evenement.`,
  ko = `Het evenement is al begonnen. Het is niet meer mogelijk om verzoeken in te dienen om mee te doen.`,
  Ao = `Waarom was jouw spel niet geselecteerd?`,
  jo = `%1$s is verwijderd uit %2$s`,
  Mo = `%2$s is voor spellen die nog niet zijn uitgebracht. %1$s is nu beschikbaar op Steam, dus het voldoet niet meer aan de vereisten voor deelname. Het is daarom verwijderd uit het evenement. Je hoeft verder niets te doen.`,
  No = `Het spel was verwijderd op %1$s.`,
  Po = `Het Steam Next Festival is niet bedoeld voor mods. %1$s is een mod op Steam en is daarom verwijderd uit %2$s. Je hoeft verder niets te doen.`,
  Fo = `Je spel is niet automatisch geselecteerd omdat je uitgavedatum is ingesteld op een datum in het verleden. Als je uitgavedatum is ingesteld op een datum in het verleden, maar het spel is nog niet uitgegeven, dan kun je via onderstaande knop een verzoek indienen om deel te nemen.`,
  Io = `Registratie voor het Next Festival: vragen en antwoorden`,
  Lo = `Het Next Festival: vragen en antwoorden`,
  Ro = `Enquête: %1$s`,
  zo = `Spel: %1$s`,
  Bo = `Bedankt voor je deelname aan %1$s!`,
  Vo = `Deze korte enquête geeft ons beter inzicht in je ervaringen met dit evenement en helpt ons de manier waarop we evenementen op Steam organiseren in de toekomst te verbeteren.`,
  Ho = `Ongeldige enquête`,
  Uo = `Antwoorden verzenden voor deze enquête`,
  Wo = `Mijn antwoorden verzenden aan Steam?`,
  Go = `Bedankt, je antwoorden zijn verzonden.`,
  Ko = `Sorry, er is een fout opgetreden bij het verzenden van je antwoorden. Probeer het later opnieuw.`,
  qo = `Hoe tevreden was je met de communicatie van Valve rond het Next Festival?`,
  Jo = `<1>Uitstekend:</1> het proces en de deadlines waren helemaal duidelijk.`,
  Yo = `<1>Goed:</1> ik begreep grotendeels wat de bedoeling was en wat de deadlines waren.`,
  Xo = `<1>Ontevreden:</1> ik vond het proces onduidelijk of verwarrend.`,
  Zo = `Kun je aangeven wat je onduidelijk of verwarrend vond?`,
  Qo = `Hoeveel mensen werken er fulltime aan je spel?`,
