  ns = `<1>11+</1> Een redelijk groot team.`,
  rs = `Voldeed je deelname aan het Next Festival aan je verwachtingen?`,
  is = `<1>Ja:</1> het evenement voldeed aan mijn verwachtingen.`,
  as = `<1>Nee:</1> ik had meer van het evenement verwacht.`,
  os = `Op welk gebied is het Next Festival volgens jou tekortgeschoten?`,
  ss = `Heb je na je deelname aan het Next Festival je uitgaveplannen gewijzigd?`,
  cs = `<1>Nee:</1> we liggen op schema en gaan door zoals gepland!`,
  ls = `<1>Ja:</1> we hebben de uitgavedatum of inhoud van het spel aangepast naar aanleiding van het Next Festival.`,
  us = `Op welke manier heb je je plannen gewijzigd? Waarom?`,
  ds = `Heb je feedback of suggesties?`,
  fs = `Wat kunnen we doen om het Next Festival beter te maken?`,
  ps = `Build %1$s is nu live voor spelers in de branch '%2$s'`,
  ms = `Vertel je spelers nu over je wijzigingen`,
  hs = `Spelers die je spel geïnstalleerd hebben, zullen een download in de wachtrij zien staan voor deze update. Ze willen vast weten wat er veranderd is.`,
  gs = `Gebruik het formulier hier rechts om dit als een kleine update te plaatsen, of open de volledige editor om je wijzigingen als een gewone of een grote update te publiceren.`,
