  Bj = `Vroegst mogelijke uitgave: %1$s`,
  Vj = `Je vroegst mogelijke uitgave is twee weken nadat je winkelpagina zichtbaar is als 'Binnenkort verwacht' of 21 dagen na de eerste aankoop van een appcredit. Plan dus goed vooruit.`,
  Hj = `Je vroegst mogelijke uitgave is twee weken nadat je winkelpagina zichtbaar is als 'Binnenkort verwacht'. Plan dus goed vooruit.`,
  Uj = `Geef de datum op waarop je van plan bent je applicatie op Steam uit te geven. Als deze datum nog ver in de toekomst ligt, geef dan een voorlopige schatting op. Als je de uitgavedatum moet uitstellen, moet je de datum hier minstens twee weken voor de eerder opgegeven datum wijzigen.`,
