  Gj = `Alle tijden zijn in Pacific Time (PST/PDT).`,
  Kj = `Je voorgenomen uitgavedatum is momenteel ingesteld op %1$s. Mocht je deze datum willen wijzigen, neem dan <1>hier contact op met Valve</1> en vermeld de reden voor de wijziging en de gewenste nieuwe datum. Het moet vrijwel zeker zijn dat dit de datum is waarop je je product zult uitgeven.`,
  qj = `OPMERKING: Omdat je pagina 'Binnenkort verwacht' live is, wordt de winkelpagina onmiddellijk gepubliceerd als je de uitgavedatum verandert. Dit is nodig om de nieuwe uitgavedatum weer te geven. Alle openstaande bewerkingen van je winkelpagina worden dan ook gepubliceerd.`,
