  fM = `Optie beschikbaar tot 14 dagen na uitgave`,
  pM = `Zie documentatie over verlanglijsten`,
  mM = `Als je je demo uitgeeft, kun je ervoor kiezen om alle spelers die je volledige spel op hun verlanglijst hebben staan een melding te sturen. Deze optie is één keer beschikbaar tot twee weken na de uitgave van je demo. Verlanglijstmeldingen moeten minstens twee weken gespreid worden, dus als je van plan bent om je spel binnen twee weken uit te brengen, is het misschien beter om deze melding niet nu te verzenden.`,
  hM = `Je basisspel wordt binnen twee weken uitgebracht, op %1$s. Als je nu een melding verzendt naar alle gebruikers met je spel op hun verlanglijst, dan kun je ze geen e-mail sturen als je spel volledig wordt uitgebracht!`,
