  wM = `Je basisspel en je demo hebben verschillende soorten beperkingen in bepaalde landen. E-mails over titels op de verlanglijst worden alleen verstuurd naar klanten die toegang hebben tot zowel het basisspel als de demo. Basisspel: %1$s. Demo: %2$s.`,
