  AM = `Gebruikers met dit spel op hun verlanglijst e-mailen over de uitgave van deze demo?`,
  jM = `Wil je een e-mail verzenden naar alle gebruikers die je spel op hun verlanglijst hebben staan, om ze op de hoogte te brengen van de uitgave van je demo?`,
  MM = `Belangrijke beperkingen`,
  NM = `<1><2>Je kunt gebruikers met je spel op hun verlanglijst maar één keer een e-mail verzenden over de uitgave van een demo.</2> Zelfs als je de demo deactiveert en in de toekomst weer activeert, blijft de limiet van één e-mail van kracht.</1><1><2>Steam stuurt spelers maximaal één e-mail per twee weken.</2> Als je je volledige spel binnen twee weken na deze e-mail uitbrengt, zal Steam de gebruikers die nu een e-mail krijgen, niet nogmaals een e-mail sturen. Houd hier rekening mee in je planning.</1>`,
