  CN = `Aanpasbare moeilijkheidsgraad`,
  wN = `Moeilijkheidsinstellingen geven spelers de mogelijkheid om hun spelervaring aan te passen aan hun bekwaamheid en voorkeuren.`,
  TN = `Altijd opslaan`,
  EN = `Spelers kunnen hun gameplay automatisch en handmatig opslaan. Opslaan is op elk gewenst moment mogelijk. Als spelers zien dat deze functie wordt aangeboden, weten ze dat ze hun voortgang in het spel kunnen behouden.`,
  DN = `Voorgelezen spelmenu's`,
  ON = `Spelers kunnen de spelmenu's beluisteren met gesproken audio.`,
  kN = `Spelers met een zichtbeperking zijn mogelijk afhankelijk van gesproken audio om menu's te kunnen gebruiken. Als je spel voorgelezen spelmenu's heeft, heb je de beslisboom van je interface beschikbaar gemaakt voor schermlezers (bijvoorbeeld via <1>Microsoft UI Automation</1>) of heb je gesproken audio in je spel opgenomen voor alle spelmenu's en meldingen. Raadpleeg voor aanbevelingen de <2>Steamworks-documentatie over toegankelijkheidsfuncties</2>.`,
