  MN = `Nee, mijn spel heeft geen voorgelezen spelmenu's.`,
  NN = `Speelbaar zonder gezichtsvermogen`,
  PN = `Spelers kunnen het spel volledig spelen zonder het scherm te hoeven zien. Je spel is ontworpen voor gameplay waarbij gezichtsvermogen niet relevant is (bijv. gericht op geluid) of je ondersteuning voor schermlezers of voorlezen is zo doeltreffend dat spelers met behulp daarvan het hele spel kunnen ervaren.`,
  FN = `Sommige spellen zijn speelbaar zonder dat spelers het scherm hoeven zien. Een spel kan bijvoorbeeld volledig op geluid zijn gebaseerd of kan schermlezers of voorlezen in die mate ondersteunen dat spelers de volledige ervaring krijgen zonder iets te hoeven zien.`,
  IN = `Is je spel speelbaar zonder gezichtsvermogen?`,
  LN = `Ja, spelers kunnen spelen zonder het scherm te hoeven zien.`,
  RN = `Nee, mijn spel is niet speelbaar zonder gezichtsvermogen.`,
  zN = `Aangepaste volumebesturing`,
  BN = `Het volume voor verschillende soorten spelgeluid kan afzonderlijk worden ingesteld.`,
  VN = `Spelers kunnen afleidende geluiden zachter zetten, zodat ze zich kunnen concentreren op de geluiden die van belang zijn. Als je spel aangepaste volumebesturing heeft, kunnen spelers de relatieve geluidsniveaus van verschillende onderdelen zoals muziek, geluidseffecten, omgevingsgeluid en spraak van personages aanpassen. Een enkele geluidsregelaar is niet voldoende om deze functie aan te vinken. Raadpleeg voor aanbevelingen de <1>Steamworks-documentatie over toegankelijkheidsfuncties</1>.`,
  HN = `Heeft je spel aangepaste volumebesturing?`,
  UN = `Ja, spelers kunnen het relatieve volume van verschillende soorten geluid in mijn spel aanpassen.`,
  WN = `Nee, mijn spel heeft geen aangepaste volumebesturing.`,
  GN = `Gericht geluid`,
  KN = `Spelers zijn mogelijk afhankelijk van audio om de locatie van spelobjecten te bepalen. Als je spel stereogeluid heeft, wordt de relatieve positie van een geluid overgebracht door het linker- danwel het rechteraudiokanaal te gebruiken. Als je spel surroundgeluid heeft, kunnen spelers het geluid uit alle richtingen horen komen, ook als dit van boven, onder, achter of voor de speler is.`,
  qN = `Welk soort gericht geluid ondersteunt je spel?`,
  JN = `Surroundgeluid: gericht geluid, bijvoorbeeld 3.1, 5.1, 7.1 of vergelijkbare tech­no­lo­gieën.`,
  YN = `Stereogeluid: linker- en rechterkanalen.`,
  XN = `Mijn spel heeft geen gericht geluid.`,
  ZN = `Stereogeluid`,
  QN = `Spelers kunnen horen van hoe ver naar links of rechts een geluid afkomstig is.`,
  $N = `Surroundgeluid`,
  eP = `Spelers kunnen horen van hoe ver in elke richting een geluid afkomstig is.`,
  tP = `Visueel`,
  nP = `Geef aan welke van de volgende visuele toegankelijkheidsfuncties je spel ondersteunt. Raadpleeg voor meer informatie over visuele toegankelijkheidsfuncties de <1>Steamworks-documentatie over toegankelijkheidsfuncties</1>.`,
  rP = `Welke van deze visuele toegankelijkheidsfuncties worden door je spel ondersteund?`,
  iP = `Aanpasbare tekstgrootte`,
  aP = `Spelers kunnen de tekstgrootte aanpassen voor tekst in het spel, menu's, dialogen van personages of ondertitels.`,
  oP = `Ondertitelopties`,
  sP = `Spelers hebben opties om de weergave van ondertitels voor alle gesproken inhoud en essentiële geluiden aan te passen. Elementaire ondertiteling is mogelijk niet voldoende voor spelers met een zichtbeperking. Met opties voor doorzichtigheid van de achtergrond, tekstkleur en -grootte kunnen spelers de ondertitels naar wens aanpassen.`,
  cP = `Kleuralternatieven`,
  lP = `Bij de gameplay worden geen kleuren gebruikt om belangrijke informatie over te brengen, of spelers hebben de mogelijkheid om de kleuren die worden gebruikt voor het overbrengen van informatie aan te passen.`,
  uP = `Cameracomfort`,
  dP = `Spelers hebben de optie om onprettige camerabewegingen aan te passen of uit te schakelen, of deze effecten komen niet in je spel voor. Voorbeelden van dit soort camerabewegingen zijn schudden, zwenken van de camera of bewegingsvervaging.`,
  fP = `Contrastinstellingen`,
