  mP = `Invoer`,
  hP = `Sommige spelers hebben toegankelijkheidshulpmiddelen die functies toewijzen aan toetsenbord, muis of touchbesturing, of spelers kunnen de voorkeur geven aan deze typen invoer. Raadpleeg voor meer informatie over toegankelijkheidsfuncties voor invoer de <1>Steamworks-documentatie over toegankelijkheidsfuncties</1>.`,
  gP = `Welke van deze toegankelijkheidsfuncties voor invoer worden door je spel ondersteund?`,
  _P = `Optie voor alleen toetsenbord`,
  vP = `Spelers kunnen het spel spelen met alleen een toetsenbord, zonder gebruik te maken van andere invoermethoden zoals een muis of controller.`,
  yP = `Optie voor alleen muis`,
  bP = `Spelers kunnen het spel spelen met alleen een muis, zonder gebruik te maken van andere invoermethoden zoals een toetsenbord of controller.`,
