  SP = `Spelers kunnen het spel spelen met alleen touchbesturing, zonder gebruik te maken van andere invoermethoden zoals een muis, toetsenbord of controller.`,
  CP = `Tijdgevoelige invoer`,
  wP = `Sommige spelers zijn mogelijk niet in staat om tijdgevoelige invoer van welk type dan ook te gebruiken. Voor andere kan het onprettig of onmogelijk zijn om knoppen in te drukken met precieze timing (Quick Time Events) of om knoppen snel achter elkaar in te drukken (button mashing). Bij sommige spellen, zoals visuele novelles of spellen met beurten, is het niet nodig om invoer te timen.`,
  TP = `Welke type tijdgevoelige invoer is vereist voor je spel?`,
  EP = `Voor mijn spel is de timing van invoer niet van belang. Spelers kunnen net zo lang doen over hun volgende zet als ze willen.`,
  DP = `Mijn spel is afhankelijk van tijdgevoelige invoer, maar maakt geen gebruik van Quick Time Events.`,
  OP = `Voor mijn spel zijn Quick Time Events vereist.`,
  kP = `Speelbaar zonder Quick Time Events`,
  AP = `Spelers kunnen sequenties waarbij knoppen met precieze timing moeten worden ingedrukt ('Quick Time Events') of het snel indrukken van knoppen ('button mashing') vermijden.`,
  jP = `Speelbaar in je eigen tempo`,
  MP = `Spelers kunnen net zo lang doen over hun volgende zet als ze willen, of onderdelen waarvoor specifieke timing vereist is, kunnen worden uitgeschakeld of overgeslagen.`,
  NP = `Tekst naar spraak & spraak naar tekst`,
  PP = `Sociale functies in een spel zoals tekst- en spraakchat zijn mogelijk niet beschikbaar voor spelers met een zicht- of gehoorbeperking. Met de functie voor tekst naar spraak wordt de tekstchat live voorgelezen en met de functie voor spraak naar tekst, kunnen spelers de tekst van de spraakchat live meelezen. Raadpleeg voor aanbevelingen voor spraak naar tekst of tekst naar spraak de <1>Steamworks-documentatie over toegankelijkheidsfuncties</1>.`,
  FP = `Welke van deze functies worden door je spel ondersteund?`,
