  wF = `Ondersteuning voor ALGEMENE INVOER`,
  TF = `Om zo goed mogelijk te bepalen welke controllers je spel ondersteunt, hebben we een snelle wizard opgezet met een aantal korte vragen.

Beantwoord de vragen van de wizard zo goed mogelijk, zodat Steam spellen aan spelers kan voorstellen die goed werken met de apparaten die zij hebben.`,
  EF = `Let op: Alle VR-apparaten die je spel ondersteunt, inclusief invoerapparaten, moet je beschrijven in de systeemvereisten. De controllerondersteuning die je hier beschrijft, moet verwijzen naar de ondersteuning in bureaublad- of Big Picture-modus.`,
  DF = `Met welke apparaten kun je jouw spel comfortabel spelen?`,
