  zF = `Ja, mijn spel is volledig geïntegreerd met de Steam Input-API.`,
  BF = `Nee, mijn spel maakt geen gebruik van de Steam Input-API.`,
  VF = `Xbox-controllerondersteuning`,
  HF = `Als je spel Xbox-controllers volledig ondersteunt, kan een speler je spel starten, configureren, spelen en afsluiten zonder een toetsenbord nodig te hebben. Om van volledige Xbox-controllerondersteuning te kunnen spreken, moet het volgende mogelijk zijn in je spel:`,
  UF = `Een speler moet alles in het spel kunnen doen met enkel de controller. Dit omvat het doorlopen van alle launchers vóór het spel, het spel spelen, het gebruiken van menu's, het veranderen van instellingen en het afsluiten van het spel.`,
  WF = `Wanneer de controller is losgekoppeld, moet het spel worden gepauzeerd, tenzij het een spel voor meerdere spelers is.`,
  GF = `Elke prompt om tekst in te voeren moet een virtueel toetsenbord openen op het scherm.`,
  KF = `Als je spel de modus 'Lokale multiplayer' ondersteunt, moet deze modus werken met meerdere controllers.`,
  qF = `Voldoet je spel aan de bovenstaande criteria voor volledige Xbox-controllerondersteuning?`,
  JF = `PlayStation-controllerondersteuning`,
  YF = `Als je spel een of meerdere PlayStation-controllermodellen uit de onderstaande lijst ondersteunt, moet het voor een speler met die controller mogelijk zijn om alles in je spel te doen wat ook met een Xbox-controller kan. Om aangemerkt te worden als spel dat PlayStation-controllers ondersteunt, moet je spel ook minstens aan de volgende eisen voldoen:`,
  XF = `De juiste symbolen (pictogrammen) worden op het scherm getoond wanneer de gebruiker wordt gevraagd om een bepaalde knop op de controller in te drukken.`,
  ZF = `Het is mogelijk om het spel te spelen, met menu's te communiceren, instellingen te wijzigen en het spel af te sluiten.`,
  QF = `<1>Opmerking over USB/bluetooth:</1> Bij het gebruik van PlayStation-controllers op pc gebeurt het regelmatig dat de USB-verbinding goed werkt, maar dat bluetooth-verbindingen niet op hetzelfde niveau worden ondersteund. Vraag na bij je technische team of het spel inderdaad met bluetooth werkt voordat je de onderstaande optie selecteert.`,
  $F = `<1>Ja</1>, mijn spel ondersteunt: (selecteer alles wat van toepassing is)`,
  eI = `Integratie met de Steam Input-API`,
  tI = `Als je spel volledig geïntegreerd is met de Steam Input-API, dan werkt het met zowat elk van de meer dan 200 controllermodellen die een speler kan aansluiten, inclusief toekomstige modellen. Als je dit type ondersteuning voor je spel selecteert, bevestig je dat je spel aan de volgende eisen voldoet:`,
  nI = `Het spel kan acties van de Steam Input-API implementeren en de herkomst van de betreffende acties herleiden, zodat de juiste controllersymbolen in het spel worden weergegeven voor de meestgebruikte controllermodellen.`,
