  vR = `Als je er klaar voor bent om spelers te vertellen dat je inhoud voor de seizoenspas hebt uitgebracht, kun je de optie 'Markeren als uitgebracht' hieronder selecteren en de instructies volgen. Lees voor meer informatie de <1>documentatie over uitgaven voor seizoenspassen</1>.`,
