  Mz = `Hieronder staan een aantal evenementen waar leden van het Steam-team mogelijk aanwezig zullen zijn. Als je ook van plan bent om een van deze evenementen te bezoeken, of in de buurt woont, en interesse hebt in een persoonlijke ontmoeting, laat ons dit dan weten via het onderstaande formulier. We gebruiken deze informatie om ons reis- en evenementprogramma beter af te stemmen. Als je je registreert voor een van deze evenementen, krijg je voorrang als we onze uitnodingen gaan verzenden.`,
